// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address[] memory tos, uint256[] memory v) public {
        vm.assume(caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, v));
        assertTrue(!success, "Non-authorized caller should revert");
    }
}

